#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countSubarraysWithEvenOddDiff(std::vector<int>& nums, int diff) {
        std::unordered_map<int, int> counts;
        counts[0] = 1;
        int cur = 0;
        long long ans = 0;
        for (int x : nums) {
            cur += (x % 2 == 0) ? 1 : -1;
            ans += counts[cur - diff];
            counts[cur]++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countSubarraysWithEvenOddDiff(int[] nums, int diff) {
        Map<Integer, Integer> counts = new HashMap<>();
        counts.put(0, 1);
        int cur = 0;
        long ans = 0;
        for (int x : nums) {
            cur += (x % 2 == 0) ? 1 : -1;
            ans += counts.getOrDefault(cur - diff, 0);
            counts.put(cur, counts.getOrDefault(cur, 0) + 1);
        }
        return ans;
    }
}

